   833	fn path_ends_with_ci(path: &str, suffix: &str) -> bool {
   834	    let path = path.trim_end_matches(['/', '\\']);
   835	    let suffix = suffix.trim_matches('/');
   836	    if suffix.is_empty() || suffix.len() > path.len() {
   837	        return false;
   838	    }
   839	    path.as_bytes()[path.len() - suffix.len()..]
   840	        .iter()
   841	        .zip(suffix.as_bytes())
   842	        .all(|(&left, &right)| {
   843	            (left == b'\\' && right == b'/') || left.eq_ignore_ascii_case(&right)
   844	        })
   845	}
