+fn run_eval(from_feedback: bool, source: Option<String>, limit: usize, json_output: bool) -> Result<()> {
+    if !from_feedback {
+        bail!("eval currently requires --from-feedback");
+    }
+    if limit == 0 {
+        bail!("--limit must be at least 1");
+    }
+    let root = platform_cache_root()?;
+    let (entries, _) = feedback::list_feedback(&root, usize::MAX)?;
+    let cases = entries
+        .into_iter()
+        .filter_map(|entry| Some((entry.query?, entry.expected?)))
+        .collect::<Vec<_>>();
+    let source = source.unwrap_or_else(|| ".".to_owned());
+    let index = build_sparse_index(
+        &source,
+        CacheConfig::Platform,
+        false,
+        true,
+        None,
+    )?;
+    let mut hits = 0usize;
+    let mut results = Vec::new();
+    for (query, expected) in &cases {
+        let search = SearchOptions::new(limit).with_mode(SearchMode::Bm25);
+        let found = index.search_with(query, &search)?;
+        let rank = found
+            .iter()
+            .position(|result| result.chunk.location().starts_with(expected) || result.chunk.file_path == *expected)
+            .map(|idx| idx + 1);
+        if rank.is_some() {
+            hits += 1;
+        }
+        results.push(json!({
+            "query": query,
+            "expected": expected,
+            "rank": rank,
+            "hit": rank.is_some(),
+        }));
+    }
+    let hit_rate = if cases.is_empty() {
+        0.0
+    } else {
+        hits as f64 / cases.len() as f64
+    };
+    let payload = json!({
+        "source": source,
+        "cases": cases.len(),
+        "hits": hits,
+        "hit_rate": hit_rate,
+        "limit": limit,
+        "results": results,
