use ndarray::Array2;
use sifs::{
    CacheConfig, Chunk, Encoder, EncoderSpec, HashingEncoder, IndexOptions, ModelLoadPolicy,
    ModelOptions, SearchMode, SearchOptions, SearchResult, SifsIndex, format_results,
};
use std::fs;
