pub fn filter_extensions(
    extensions: Option<HashSet<String>>,
    include_text_files: bool,
) -> HashSet<String> {
    if let Some(extensions) = extensions {
        return extensions;
    }
    FILE_TYPES
        .iter()
        .filter(|(_, ft)| ft.category == FileCategory::Code || include_text_files)
        .map(|(ext, _)| (*ext).to_owned())
        .collect()
}

pub fn walk_files(
    root: &Path,
    extensions: &HashSet<String>,
    ignore: Option<&HashSet<String>>,
) -> Vec<PathBuf> {
    let ignore_owned = ignore.cloned().unwrap_or_default();
    let mut builder = WalkBuilder::new(root);
    builder
        .hidden(true)
        .parents(true)
        .ignore(true)
        .git_ignore(true)
        .git_exclude(true)
        .git_global(true)
        .require_git(false)
        .filter_entry(move |entry| {
            let name = entry.file_name().to_string_lossy();
            !DEFAULT_IGNORED_DIRS.contains(name.as_ref()) && !ignore_owned.contains(name.as_ref())
        });
    let files: Vec<PathBuf> = builder
        .build()
        .filter_map(Result::ok)
        .filter(|entry| entry.file_type().is_some_and(|ft| ft.is_file()))
        .map(|entry| entry.into_path())
        .filter(|path| {
            path.extension()
                .map(|ext| {
                    extensions
                        .contains(format!(".{}", ext.to_string_lossy().to_lowercase()).as_str())
                })
                .unwrap_or(false)
        })
        .collect();
    let mut files = files;
    files.sort();
    files
}

