struct EvalCommand {
    from_feedback: bool,
    source: Option<String>,
    mode: Option<ModeArg>,
    all_modes: bool,
    limit: usize,
    model: Option<String>,
    encoder: EncoderArg,
    offline: bool,
    no_download: bool,
    json: bool,
}

fn run_pack(
    query: String,
    invocation: ResolvedInvocation,
    budget_tokens: usize,
    json_output: bool,
) -> Result<()> {
    if budget_tokens == 0 {
        bail!("--budget-tokens must be at least 1");
    }
    if invocation.limit == 0 {
        bail!("--limit must be at least 1");
    }
    let policy = model_policy(invocation.offline, invocation.no_download);
    let index = build_index_for_mode(
        &invocation.source,
        invocation.mode,
        encoder_spec(invocation.encoder, invocation.model.as_deref(), policy),
        invocation.cache,
        invocation.offline,
        invocation.include_docs,
        extension_set(&invocation.extensions),
    )?;
    let options = SearchOptions::new(invocation.limit).with_mode(invocation.mode);
    let results = index.search_with(&query, &options)?;
    let mut remaining_chars = budget_tokens.saturating_mul(4);
    let mut seen = std::collections::HashSet::new();
    let mut packed = Vec::new();
    for result in results {
        if remaining_chars == 0 || !seen.insert(result.chunk.file_path.clone()) {
            continue;
        }
        let content = if result.chunk.content.len() > remaining_chars {
            result
                .chunk
                .content
                .chars()
                .take(remaining_chars)
                .collect::<String>()
        } else {
            result.chunk.content.clone()
        };
        remaining_chars = remaining_chars.saturating_sub(content.len());
        packed.push(json!({
            "file_path": result.chunk.file_path,
            "start_line": result.chunk.start_line,
            "end_line": result.chunk.end_line,
            "score": result.score,
            "source": result.source.to_string(),
            "why": format!("ranked by {} for the pack query", invocation.mode),
            "symbols": result.chunk.symbols,
            "breadcrumbs": result.chunk.breadcrumbs,
            "content": content,
        }));
    }
    let payload = json!({
        "query": query,
        "source": invocation.source,
        "mode": invocation.mode.to_string(),
        "limit": invocation.limit,
        "budget_tokens": budget_tokens,
        "estimated_tokens_used": (budget_tokens.saturating_mul(4).saturating_sub(remaining_chars) + 3) / 4,
        "stats": index.stats(),
        "warnings": index.warnings(),
        "items": packed,
    });
    if json_output {
        println!("{}", serde_json::to_string_pretty(&payload)?);
    } else {
        println!("{}", serde_json::to_string_pretty(&payload)?);
    }
    Ok(())
}

