        .enumerate()
        .map(|(rank, (idx, score))| {
            (
                *idx,
                RankEvidence {
                    rank: rank + 1,
                    score: *score,
                },
            )
        })
        .collect()
}

fn add_rrf_scores<S: std::hash::BuildHasher>(
    combined: &mut HashMap<usize, f32, S>,
    ranked: Vec<(usize, f32)>,
    weight: f32,
) {
    for (rank, (id, _)) in ranked.into_iter().enumerate() {
        *combined.entry(id).or_default() += weight / (RRF_K + rank as f32 + 1.0);
    }
}

