+fn add_symbol_candidate_scores<S: std::hash::BuildHasher>(
+    combined: &mut HashMap<usize, f32, S>,
+    query: &str,
+    symbol_mapping: Option<&HashMap<String, Vec<usize>>>,
+    selector: Option<&[usize]>,
+) {
+    let Some(symbol_mapping) = symbol_mapping else {
