+    let selector_set = selector.map(|values| values.iter().copied().collect::<std::collections::HashSet<_>>());
+    let mut injected = 0usize;
+    for term in symbol_query_terms(query) {
+        let Some(postings) = symbol_mapping.get(&term) else {
