        fs::read_to_string(root.join("src/search.rs")).unwrap(),
    ]
    .join("\n")
    .to_lowercase();
    let allow = [
        "click", "curl", "express", "flask", "gin", "plug", "rack", "rails", "redis", "serde",
        "tokio",
