+        || lowered.starts_with("what ")
+        || lowered.starts_with("where ")
+        || lowered.starts_with("when ")
+        || lowered.starts_with("why ")
+        || lowered.starts_with("which ")
+        || lowered.starts_with("who ")
+        || lowered.contains(" architecture")
+        || lowered.contains(" design")

