impl CacheContext {
    fn for_source(
        source_id: String,
        _root: &Path,
        extensions: &Option<HashSet<String>>,
        ignore: &Option<HashSet<String>>,
        include_text_files: bool,
    ) -> Self {
        let options_id = cache_hash(&(
