pub fn search_semantic(
    query: &str,
    model: &dyn Encoder,
    semantic_index: &DenseIndex,
    _chunks: &[Chunk],
    top_k: usize,
    selector: Option<&[usize]>,
    explain: bool,
) -> Vec<SearchHit> {
    let encoded = model.encode(&[query.to_owned()]);
    let vector = normalize_vector(encoded.row(0).to_owned());
    semantic_index
        .query(&vector, top_k, selector)
        .into_iter()
        .enumerate()
        .map(|(rank, (idx, score))| SearchHit {
            chunk_id: idx,
            score,
            source: SearchMode::Semantic,
            explanation: explain.then(|| SearchExplanation {
                alpha: None,
                bm25_rank: None,
                bm25_score: None,
                semantic_rank: Some(rank + 1),
                semantic_score: Some(score),
                rrf_score: None,
                boosted_score: None,
                final_score: score,
            }),
        })
        .collect()
}

pub fn search_bm25(
    query: &str,
    bm25_index: &Bm25Index,
    _chunks: &[Chunk],
    top_k: usize,
    selector: Option<&[usize]>,
    explain: bool,
) -> Vec<SearchHit> {
    bm25_index
        .search(query, top_k, selector)
        .into_iter()
        .enumerate()
        .map(|(rank, (idx, score))| SearchHit {
            chunk_id: idx,
            score,
            source: SearchMode::Bm25,
            explanation: explain.then(|| SearchExplanation {
                alpha: None,
                bm25_rank: Some(rank + 1),
                bm25_score: Some(score),
                semantic_rank: None,
                semantic_score: None,
                rrf_score: None,
                boosted_score: None,
                final_score: score,
            }),
        })
        .collect()
}

