mod tests {
    use super::{apply_query_boost, boost_path_intent, rerank_topk, resolve_alpha};
    use crate::types::Chunk;
    use std::collections::HashMap;

    fn chunk(content: &str, file_path: &str) -> Chunk {
        Chunk {
            content: content.to_owned(),
            file_path: file_path.to_owned(),
            start_line: 1,
            end_line: 1,
            language: Some("python".to_owned()),
            symbols: Vec::new(),
            breadcrumbs: Vec::new(),
        }
    }

    #[test]
    fn boosts_definitions_and_penalizes_tests() {
        let defining = chunk("class MyService:\n    pass", "src/my_service.py");
        let other = chunk("x = MyService()", "src/utils.py");
        let chunks = vec![defining, other];
        let mut scores = HashMap::new();
        scores.insert(1usize, 0.4);
        let boosted = apply_query_boost(&scores, "MyService", &chunks);
        assert!(boosted[&0] > boosted[&1]);

        let regular = chunk("def impl(): pass", "src/regular.py");
        let test = chunk("def impl(): pass", "tests/test_auth.py");
        let chunks = vec![regular, test];
        let scores = HashMap::from([(0usize, 1.0), (1usize, 1.0)]);
        let ranked = rerank_topk(&scores, &chunks, 2, true);
        assert_eq!(ranked[0].0, 0);
    }

    #[test]
    fn path_penalties_follow_query_intent() {
        let regular = chunk("fn impl(): pass", "src/auth.py");
        let test = chunk("fn impl(): pass", "tests/test_auth.py");
        let typedef = chunk("export interface User {}", "src/user.d.ts");
        let chunks = vec![regular, test, typedef];
        let scores = HashMap::from([(0usize, 1.0), (1usize, 1.0), (2usize, 1.0)]);

        let default_ranked = super::rerank_topk_for_query(&scores, &chunks, 3, true, "auth flow");
        assert_eq!(default_ranked[0].0, 0);

        let test_ranked =
            super::rerank_topk_for_query(&scores, &chunks, 3, true, "auth test coverage");
        assert!(
            test_ranked
                .iter()
                .any(|(id, score)| *id == 1 && *score == 1.0)
        );

        let type_ranked =
            super::rerank_topk_for_query(&scores, &chunks, 3, true, "public api type");
        assert!(
            type_ranked
                .iter()
                .any(|(id, score)| *id == 2 && *score == 1.0)
        );
    }

    #[test]
