        let mut scores = HashMap::from([(0usize, 1.0), (1usize, 1.0), (2usize, 1.0)]);

        boost_path_intent(&mut scores, "core v4 runtime builder", 1.0, &chunks, None);

        assert!(scores[&1] > scores[&2]);
        assert!(scores[&2] > scores[&0]);
    }

