        params = np.array(self.pose.params5, dtype=np.float64, copy=True)
        setup = self.setup
        transfers: list[GaugeTransfer] = []
        if params.size == 0:
            return self, GaugeReport(())

        dx_mean = float(np.mean(params[:, 3]))
