            setup = replace(setup, det_v_px=setup.det_v_px + dz_mean)
            transfers.append(GaugeTransfer("mean(dz_px)", "det_v_px", dz_mean, "native_detector_px"))

        return GeometryState(setup=setup, pose=PoseParameters(params)), GaugeReport(tuple(transfers))

