    def from_dict(cls, payload: Mapping[str, object]) -> GeometryState:
        setup_payload = payload.get("setup", {})
        if not isinstance(setup_payload, Mapping):
            raise TypeError("setup must be a mapping")
        pose_payload = payload.get("pose", [])
        if not isinstance(pose_payload, list):
            raise TypeError("pose must be a list of row mappings")
        rows = []
        for row in pose_payload:
            if not isinstance(row, Mapping):
                raise TypeError("pose rows must be mappings")
            rows.append(
                [
                    float(row["alpha_rad"]),
                    float(row["beta_rad"]),
                    float(row["phi_residual_rad"]),
                    float(row["dx_px"]),
                    float(row["dz_px"]),
                ]
            )
        return cls(
            setup=SetupParameters(
                det_u_px=float(setup_payload.get("det_u_px", 0.0)),
                det_v_px=_optional_float(setup_payload.get("det_v_px")),
                detector_roll_rad=float(setup_payload.get("detector_roll_rad", 0.0)),
                axis_rot_x_rad=float(setup_payload.get("axis_rot_x_rad", 0.0)),
                axis_rot_y_rad=float(setup_payload.get("axis_rot_y_rad", 0.0)),
                theta_offset_rad=float(setup_payload.get("theta_offset_rad", 0.0)),
                theta_scale=_optional_float(setup_payload.get("theta_scale")),
            ),
            pose=PoseParameters(np.asarray(rows, dtype=np.float64).reshape((-1, 5))),
        )


def _default_scale(name: str) -> float:
    if name.endswith("_px"):
        return 1.0
    if name.endswith("_rad"):
        return 1e-3
    return 1.0


def _optional_float(value: object) -> float | None:
    if value is None:
        return None
    return float(value)

