        .filter(|term| !term.is_empty())
        .flat_map(split_identifier)
        .collect()
}

fn path_stem_matches(path: &str, query_term: &str) -> bool {
    Path::new(path)
        .file_stem()
        .and_then(|stem| stem.to_str())
        .map(|stem| {
            split_identifier(stem)
                .into_iter()
                .any(|stem_term| stem_matches(&stem_term, query_term))
        })
